def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, list):
        raise TypeError("fields must be a list")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Create a dynamic class for the Point subclass
    class PointSubclass(object):
        def __init__(self, *args):
            if len(args) != len(fields):
                raise ValueError("Number of arguments must match number of fields")
            for field, value in zip(fields, args):
                setattr(self, field, value)

        def __repr__(self):
            args_str = ", ".join(f"{field}={self.{field}}" for field in fields)
            return f"{name}({args_str})"

        def to_wkt(self, srid):
            if srid not in srid_map:
                raise ValueError(f"Invalid SRID: {srid}")
            wkt_type = srid_map[srid]
            return f"{wkt_type}({','.join(str(getattr(self, field)) for field in fields)})"

    return PointSubclass

