from typing import Callable, Any, Tuple
from functools import wraps, partial
import time

def _hashable(item):
    try:
        hash(item)
        return True
    except TypeError:
        return False

def _make_key(func, args, kwds, typed):
    # If function arguments are hashable, use them directly
    if typed:
        key = args
    else:
        key = tuple(type(v) if isinstance(v, (dict, list, tuple)) else v for v in args)
    for arg in kwds.values():
        if typed:
            key += (arg,)
        else:
            key += (type(arg) if isinstance(arg, (dict, list, tuple)) else arg,)
    return key

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize <= 0:
        return lambda f: f
    if ttl <= 0:
        return caches.memoize(maxsize=maxsize, typed=typed)

    class TTLCache(CacheDecorationClass):
        def __init__(self, cache=None, typed=False, timer=timer):
            # cache can be None, which defaults to Python's dict
            self.cache = cache or {}
            self.maxsize = maxsize
            self.timer = timer
            self.ttl = ttl
            self.typed = typed

        def __getitem__(self, key):
            if key in self.cache:
                if (self.timer() - self.cache[key][-1]) < self.ttl:
                    return self.cache[key][0]
                else:
                    del self.cache[key]
            return None

        def __setitem__(self, key, value):
            if len(self.cache) >= self.maxsize:
                # Remove least recently used item that is still within TTL
                sorted_cache = sorted(self.cache.items(), key=lambda item: item[1][1])
                expiration_times = [item[1][1] for item in sorted_cache]
                oldest_time = expiration_times[0]
                for key_to_delete in [item[0] for item in sorted_cache if (self.timer() - item[1][1]) < self.ttl]:
                    del self.cache[key_to_delete]
                    break

            self.cache[key] = (value, self.timer())

        def __contains__(self, key):
            return key in self.cache

        def __delitem__(self, key):
            del self.cache[key]

    def decorator(f):
        cache = TTLCache(cache=None, typed=typed, timer=timer)
        @wraps(f)
        def wrapper(*args, **kwargs):
            key = _make_key(f, args, kwargs, typed)
            result = cache[key]
            if result is None:
                result = f(*args, **kwargs)
                cache[key] = result
            return result
        return wrapper
    return decorator

