def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    def is_descendant(subclass, parent):
        return issubclass(subclass, parent) and subclass != parent

    min_bases = []
    for cls in classes:
        if not any(is_descendant(cls, parent) for parent in min_bases):
            min_bases.append(cls)
    return min_bases

