        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    # Validate each item in the inventory
    for item in inventory:
        if 'type' in item and isinstance(item['type'], Schema):
            item['type'].validate(item, spec_version)
        else:
            raise SchemaFormatException("Missing or invalid 'type' field in item.", None)

    return inventory

