def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The input 'prior' must be an InventoryValidator object.")

    if self.inventory.version >= prior.inventory.version:
        raise ValueError("The current inventory version is not older than the prior version.")

    if self.inventory.size != prior.inventory.size:
        raise ValueError("The current inventory size does not match the prior inventory size.")

    for item_id, item in self.inventory.items():
        if item_id not in prior.inventory:
            raise ValueError(f"Item {item_id} is missing in the prior inventory.")
        if not item.equals(prior.inventory[item_id]):
            raise ValueError(f"Item {item_id} differs between the current and prior inventories.")

    print("The prior version is valid.")

