def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    valid_algorithms = {'md5', 'sha256'}
    for entry in fixity.values():
        if not isinstance(entry, dict):
            raise ValueError("Fixity entry must be a dictionary")

        if 'algorithm' not in entry or 'value' not in entry:
            raise ValueError("Fixity entry must contain 'algorithm' and 'value' keys")

        if entry['algorithm'] not in valid_algorithms:
            raise ValueError(f"Invalid algorithm: {entry['algorithm']}")

        if not isinstance(entry['value'], str):
            raise ValueError("Fixity value must be a string")

    referenced_files = fixity.keys()
    for file in referenced_files:
        if file not in manifest_files:
            raise ValueError(f"File {file} referenced in fixity block but not found in manifest")

    print("Fixity block is valid.")

