def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    try:
        if verbose:
            print(f"Running command: {' '.join(commands)} {' '.join(args)}")

        if hide_stderr:
            process = subprocess.Popen(commands + args, cwd=cwd, env=env, stderr=subprocess.STDOUT, stdout=subprocess.PIPE)
        else:
            process = subprocess.Popen(commands + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        output, err = process.communicate()

        if process.returncode != 0:
            if verbose:
                print(f"Command failed with return code {process.returncode}")
            if err:
                if verbose:
                    print(f"Error output: {err.decode()}")
                raise subprocess.CalledProcessError(process.returncode, ' '.join(commands + args), output=err)
            else:
                raise subprocess.CalledProcessError(process.returncode, ' '.join(commands + args))

        if output:
            if verbose:
                print(f"Command output: {output.decode()}")

        return output.decode()

    except Exception as e:
        if verbose:
