def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("version_dirs must not be empty")

    root_inventory = {}
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found at {inventory_path}")

        version_inventory = self.load_inventory(inventory_path)
        for content_hash, content_details in version_inventory.items():
            if content_hash not in root_inventory:
                root_inventory[content_hash] = content_details
            else:
                if root_inventory[content_hash] != content_details:
                    raise ValueError(f"Content digest mismatch for {content_hash}")

    return root_inventory

