def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    human_size_regex = r'^(\d+(\.\d+)?)\s*([KMGTPEZY]B?)?$'
    import re
    match = re.match(human_size_regex, size, re.IGNORECASE)
    if not match:
        raise ValueError(f"Invalid size format: {size}")

    bytes_value, unit = match.groups()
    bytes_value = float(bytes_value)

    if unit:
        unit = unit.upper()
        if unit == 'K':
            bytes_value *= 1024
        elif unit == 'M':
            bytes_value *= 1024 ** 2
        elif unit == 'G':
            bytes_value *= 1024 ** 3
        elif unit == 'T':
            bytes_value *= 1024 ** 4
        elif unit == 'P':
            bytes_value *= 1024 ** 5
        elif unit == 'E':
            bytes_value *= 1024 ** 6
        elif unit == 'Z':
            bytes_value *= 1024 ** 7
        elif unit == 'Y':
            bytes_value *= 1024 ** 8
        elif unit == 'B':
            bytes_value *= 1

    return int(round(bytes_value))

