import logging
import os
import tomllib
import yaml

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []
    logger = logging.getLogger(__name__)

    for config_filename in config_filenames:
        try:
            if config_filename.endswith('.toml'):
                with open(config_filename, 'rb') as fd:
                    config = tomllib.load(fd)
            elif config_filename.endswith('.yaml'):
                with open(config_filename, 'r') as fd:
                    config = yaml.safe_load(fd)
            else:
                logger.error(f'Unsupported file extension: {os.path.basename(config_filename)}')
                log_records.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=config_filename, lineno=0, msg='Unsupported file extension', args=(), exc_info=None))
                continue

            if overrides:
                config.update(overrides)

            if resolve_env:
                resolve_environment_variables(config)

            configs[config_filename] = config
        except Exception as e:
            logger.error(f'Error loading or parsing {config_filename}: {str(e)}')
            log_records.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=config_filename, lineno=0, msg=str(e), args=(), exc_info=None))

    return configs, log_records

def resolve_environment_variables(config):
    import re
    env_var_regex = re.compile(r'\$\{([A-Za-z0-9_]+)\}')

    def replace_env_var(match):
        env_var = match.group(1)
        return os.getenv(env_var, f'${{{env_var}}}')

    for key, value in config.items():
        if isinstance(value, str):
            config[key] = env_var_regex.sub(replace_env_var, value)
        elif isinstance(value, dict):
            config[key] = resolve_environment_variables(value)
        elif isinstance(value, list):
            config[key] = [resolve_environment_variables(item) if isinstance(item, dict) else item for item in value]

