def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    :param document: Webfinger document as a string.
    :return: dict parsed from the document.
    """
    try:
        parsed_json = json.loads(document)
        if '@context' in parsed_json and 'diaspora' in parsed_json['@context']:
            return parsed_json['diaspora']
        else:
            raise ValueError("Invalid JSON webfinger document")
    except json.JSONDecodeError:
        pass  # fall back to parsing XRD

    xrd = fromstring(document)
    hcard_url = xrd.find(".//ns0:Link[@rel='hcard']", namespaces={'ns0': 'http://webfinger.net/rel/jrd'}).get('href')
    salmon_url = xrd.find(".//ns0:Link[@rel='http://salmon.pobox.com/salmon']", namespaces={'ns0': 'http://webfinger.net/rel/jrd'}).get('href')
    icon_url = xrd.find(".//ns0:Link[@rel='http://microformats.org/profile/hcard']", namespaces={'ns0': 'http://webfinger.net/rel/jrd'}).get('href')

    return {
        "hcard_url": hcard_url,
        "salmon_url": salmon_url,
        "icon_url": icon_url
    }

