def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    from . import capability

    # Helper function to check if a condition is met
    def condition_met(condition, args):
        try:
            return capability.condition(condition, args)
        except Exception as e:
            raise TypeError(f"Error evaluating condition '{condition}': {e}")

    # Extract the command spec for the given command_name
    command_spec = next((c for c in options_spec if c['name'] == command_name), None)
    if not command_spec:
        raise ValueError(f"Command '{command_name}' not found in options_spec")

    # Collect arguments that have a required when condition
    required_args = []
    for arg, spec in command_spec.get('args', {}).items():
        if 'required_when' in spec:
            if all(condition_met(c, args) for c in spec['required_when']):
                required_args.append(arg)

    return required_args

